#include <Wire.h>
#include <Adafruit_GFX.h>
#include <Adafruit_SSD1306.h>

#define SCREEN_WIDTH 128
#define SCREEN_HEIGHT 64
#define OLED_ADDR 0x3C
Adafruit_SSD1306 display(SCREEN_WIDTH, SCREEN_HEIGHT, &Wire, -1);

// Пины по схеме устройства
const int PIN_BTN_PLUS  = D0;  // SW1
const int PIN_BTN_MINUS = D1;  // SW2
const int PIN_BTN_START = D2;  // SW3
const int PIN_BUZZER    = D10; // BZ1.P (активный, HIGH=пищит)
const int PIN_LED       = D3;

int setMinutes = 0;
int setSeconds = 30;
int remainSec = 30;
enum State {IDLE, RUNNING, PAUSED, RINGING};
State state = IDLE;
unsigned long lastTick = 0;
unsigned long lastBtn = 0;
bool displayOn = true;

void beep(int ms){ digitalWrite(PIN_BUZZER, HIGH); digitalWrite(PIN_LED, HIGH); delay(ms); digitalWrite(PIN_BUZZER, LOW); digitalWrite(PIN_LED, LOW); }

void drawScreen(){
  display.clearDisplay();
  display.setTextColor(SSD1306_WHITE);
  display.setCursor(0,0);
  display.setTextSize(1);
  if(state==RINGING) display.print("!! ГОТОВО !!");
  else if(state==RUNNING) display.print("Идет...");
  else if(state==PAUSED) display.print("Пауза");
  else display.print("Кухонный таймер");
  int m = remainSec/60;
  int s = remainSec%60;
  display.setCursor(10,18);
  display.setTextSize(3);
  char buf[6]; sprintf(buf,"%02d:%02d", m, s);
  display.print(buf);
  display.setTextSize(1);
  display.setCursor(0,52);
  if(state==IDLE||state==PAUSED) display.print("+/- set  START пуск");
  else if(state==RUNNING) display.print("START пауза (уд. сброс)");
  else display.print("Нажми любую кнопку");
  display.display();
}

bool btnPressed(int pin){
  if(digitalRead(pin)==LOW){ delay(30); if(digitalRead(pin)==LOW) return true; }
  return false;
}

void setup(){
  pinMode(PIN_BTN_PLUS, INPUT_PULLUP);
  pinMode(PIN_BTN_MINUS, INPUT_PULLUP);
  pinMode(PIN_BTN_START, INPUT_PULLUP);
  pinMode(PIN_BUZZER, OUTPUT); digitalWrite(PIN_BUZZER, LOW);
  pinMode(PIN_LED, OUTPUT); digitalWrite(PIN_LED, LOW);
  Wire.begin(SDA, SCL);
  display.begin(SSD1306_SWITCHCAPVCC, OLED_ADDR);
  remainSec = setMinutes*60+setSeconds;
  drawScreen();
  beep(80);
}

void loop(){
  unsigned long now = millis();
  // Кнопки с антидребезгом 200мс
  if(now - lastBtn > 180){
    if(state==RINGING && (btnPressed(PIN_BTN_START)||btnPressed(PIN_BTN_PLUS)||btnPressed(PIN_BTN_MINUS))){
      state=IDLE; remainSec=setMinutes*60+setSeconds; lastBtn=now; digitalWrite(PIN_BUZZER,LOW); drawScreen();
    } else if(state==IDLE || state==PAUSED){
      bool changed=false;
      if(btnPressed(PIN_BTN_PLUS)){ remainSec+= (remainSec<60?5:30); if(remainSec>5999) remainSec=5999; changed=true; }
      if(btnPressed(PIN_BTN_MINUS)){ remainSec-= (remainSec<=60?5:30); if(remainSec<0) remainSec=0; changed=true; }
      if(changed){ setMinutes=remainSec/60; setSeconds=remainSec%60; state=IDLE; lastBtn=now; drawScreen(); }
      if(btnPressed(PIN_BTN_START)){ if(remainSec>0){ state=RUNNING; lastTick=now; lastBtn=now; } drawScreen(); }
    } else if(state==RUNNING){
      if(btnPressed(PIN_BTN_START)){ state=PAUSED; lastBtn=now; drawScreen(); }
      // удержание START 1с для сброса - упрощено: долгое нажатие = пауза+сброс через повтор
    }
  }
  if(state==RUNNING && now - lastTick >= 1000){
    lastTick+=1000;
    remainSec--;
    if(remainSec<=0){ remainSec=0; state=RINGING; }
    drawScreen();
  }
  if(state==RINGING){
    // прерывистый сигнал 1 Гц
    digitalWrite(PIN_BUZZER, (now/400)%2==0 ? HIGH:LOW);
    digitalWrite(PIN_LED, (now/400)%2==0 ? HIGH:LOW);
  }
  delay(10);
}
